import bpy, math
from mathutils import Matrix, Vector

S = 0.01   # 100 preview units = 1 m
L = dict(torso=30, chest=28, neck=7, head=11.5, upper=30, fore=27, thigh=46, shin=45, foot=14, shW=9, hipW=5)
FLOOR, ANKLE = 89, 4
LIM = dict(knee=150, elbow=150)
REST = dict(x=0, y=0, z=0, hipH=None, lean=2, chest=0, head=4, twist=0, turn=0, look=0,
            rU=86, rF=80, lU=93, lF=86, rO=8, lO=8, fT=84, fS=97, bT=95, bS=90, fO=3, bO=3, fP=None, bP=None)

def V(p):  # preview (x fwd, y down, z = character's right) -> Blender (X fwd, Z up, -Y = right)
    return Vector((p[0] * S, -p[2] * S, (FLOOR - p[1]) * S))
def add(a, b): return (a[0] + b[0], a[1] + b[1], a[2] + b[2])
def sub(a, b): return (a[0] - b[0], a[1] - b[1], a[2] - b[2])
def mul(v, k): return (v[0] * k, v[1] * k, v[2] * k)
def dot(a, b): return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
def ln(v): return math.sqrt(dot(v, v))
def nrm(v):
    l = ln(v) or 1
    return mul(v, 1 / l)
def limb(f, a, l, o=0, side=1):
    a, o = math.radians(a), math.radians(o)
    return add(f, (math.cos(a) * math.cos(o) * l, math.sin(a) * math.cos(o) * l, side * math.sin(o) * l))
def rotY(p, c, t):
    t = math.radians(t); dx, dz = p[0] - c[0], p[2] - c[2]
    return (c[0] + dx * math.cos(t) + dz * math.sin(t), p[1], c[2] - dx * math.sin(t) + dz * math.cos(t))

def ik(root, target, a, b, pole, max_bend):
    d = sub(target, root); dist = ln(d); n = nrm(d)
    dmin = math.sqrt(a * a + b * b - 2 * a * b * math.cos(math.radians(180 - max_bend)))
    dist = min(a + b - .01, max(dmin, dist))
    cA = (a * a + dist * dist - b * b) / (2 * a * dist); sA = math.sqrt(max(0, 1 - cA * cA))
    perp = sub(pole, mul(n, dot(pole, n)))
    perp = nrm(perp) if ln(perp) > 1e-4 else (0, -1, 0)
    return add(root, add(mul(n, a * cA), mul(perp, a * sA))), add(root, mul(n, dist))

def foot_tip(knee, ankle, fwd, plantar):
    sd = nrm(sub(ankle, knee))
    if plantar is None and ankle[1] >= FLOOR - ANKLE - 3:
        return add(ankle, mul(nrm((fwd[0], 0, fwd[2])), L["foot"]))
    k = (55 if plantar is None else plantar) / 90
    neutral = sub(fwd, mul(sd, dot(fwd, sd)))
    neutral = nrm(neutral) if ln(neutral) > 1e-4 else fwd
    return add(ankle, mul(nrm(add(mul(neutral, 1 - k), mul(sd, k))), L["foot"]))

def raw(p):
    hip = (p["x"], p["y"], p["z"])
    mid = limb(hip, -90 + p["lean"], L["torso"])
    sh = limb(mid, -90 + p["lean"] + p["chest"], L["chest"])
    nk = limb(sh, -90 + p["lean"] * .5 + p["chest"] * .5, L["neck"])
    hd = limb(nk, -90 + p["lean"] + p["chest"] + p["head"] * .6, L["head"] * 2)
    shF, shB = add(sh, (0, 0, L["shW"])), add(sh, (0, 0, -L["shW"]))
    rE = limb(shF, p["rU"], L["upper"], p["rO"], 1); rH = limb(rE, p["rF"], L["fore"], p["rO"], 1)
    lE = limb(shB, p["lU"], L["upper"], p["lO"], -1); lH = limb(lE, p["lF"], L["fore"], p["lO"], -1)
    shF, shB, rE, rH, lE, lH = [rotY(q, sh, p["twist"]) for q in (shF, shB, rE, rH, lE, lH)]
    hF, hB = add(hip, (0, 0, L["hipW"])), add(hip, (0, 0, -L["hipW"]))
    fK = limb(hF, p["fT"], L["thigh"], p["fO"], 1); fAn = limb(fK, p["fS"], L["shin"], p["fO"], 1)
    bK = limb(hB, p["bT"], L["thigh"], p["bO"], -1); bAn = limb(bK, p["bS"], L["shin"], p["bO"], -1)
    s = dict(hip=hip, mid=mid, sh=sh, shF=shF, shB=shB, nk=nk, hd=hd, rE=rE, rH=rH, lE=lE, lH=lH,
             hF=hF, hB=hB, fK=fK, fAn=fAn, bK=bK, bAn=bAn)
    if p["turn"]:
        s = {k: rotY(v, hip, p["turn"]) for k, v in s.items()}
    fwd = rotY((1, 0, 0), (0, 0, 0), p["turn"]); cf = rotY((1, 0, 0), (0, 0, 0), p["turn"] + p["twist"])
    rt = rotY((0, 0, 1), (0, 0, 0), p["turn"]); cr = rotY((0, 0, 1), (0, 0, 0), p["turn"] + p["twist"])
    knee = lambda side: nrm(add(fwd, mul(rt if side == 1 else mul(rt, -1), .25)))
    elbow = lambda side: nrm(add(add(mul(cf, -1), (0, .6, 0)), mul(cr, side * .6)))
    if p.get("fFoot"): s["fK"], s["fAn"] = ik(s["hF"], p["fFoot"], L["thigh"], L["shin"], knee(1), LIM["knee"])
    if p.get("bFoot"): s["bK"], s["bAn"] = ik(s["hB"], p["bFoot"], L["thigh"], L["shin"], knee(-1), LIM["knee"])
    if p.get("rHand"): s["rE"], s["rH"] = ik(s["shF"], p["rHand"], L["upper"], L["fore"], elbow(1), LIM["elbow"])
    if p.get("lHand"): s["lE"], s["lH"] = ik(s["shB"], p["lHand"], L["upper"], L["fore"], elbow(-1), LIM["elbow"])
    s["fTo"] = foot_tip(s["fK"], s["fAn"], fwd, p["fP"]); s["bTo"] = foot_tip(s["bK"], s["bAn"], fwd, p["bP"])
    return s

def ground(k):
    p = {**REST, **k.get("pose", {})}
    if p["hipH"] is not None or p.get("fFoot") or p.get("bFoot"):
        p["y"] = FLOOR - (p["hipH"] if p["hipH"] is not None else 84)
        return p
    s = raw({**p, "y": 0})
    low = max(s["fAn"][1] + ANKLE, s["fTo"][1], s["bAn"][1] + ANKLE, s["bTo"][1])
    p["y"] = (FLOOR - low) + (p.get("y", 0) if k.get("air") else 0)
    return p

# bone: (head point, tail point, parent)
BONES = [("spine", "hip", "mid", None), ("chest", "mid", "sh", "spine"), ("neck", "sh", "nk", "chest"), ("head", "nk", "hd", "neck"),
         ("shoulder.R", "sh", "shF", "chest"), ("shoulder.L", "sh", "shB", "chest"),
         ("upper_arm.R", "shF", "rE", "shoulder.R"), ("forearm.R", "rE", "rH", "upper_arm.R"),
         ("upper_arm.L", "shB", "lE", "shoulder.L"), ("forearm.L", "lE", "lH", "upper_arm.L"),
         ("pelvis.R", "hip", "hF", "spine"), ("pelvis.L", "hip", "hB", "spine"),
         ("thigh.R", "hF", "fK", "pelvis.R"), ("shin.R", "fK", "fAn", "thigh.R"), ("foot.R", "fAn", "fTo", "shin.R"),
         ("thigh.L", "hB", "bK", "pelvis.L"), ("shin.L", "bK", "bAn", "thigh.L"), ("foot.L", "bAn", "bTo", "shin.L")]
FK = ["spine", "chest", "neck", "head", "shoulder.R", "shoulder.L", "pelvis.R", "pelvis.L"]
# IK chains: (end bone, root joint, mid joint, end joint, control name)
CHAINS = [("forearm.R", "shF", "rE", "rH", "hand.R"), ("forearm.L", "shB", "lE", "lH", "hand.L"),
          ("shin.R", "hF", "fK", "fAn", "foot_ik.R"), ("shin.L", "hB", "bK", "bAn", "foot_ik.L")]

def bone_matrix(h, t):
    y = (V(t) - V(h)).normalized()
    ref = Vector((0, 0, 1)) if abs(y.z) < .95 else Vector((1, 0, 0))
    x = y.cross(ref).normalized(); z = x.cross(y)
    m = Matrix((x, y, z)).transposed().to_4x4(); m.translation = V(h)
    return m

def pole_pos(s, root, mid, end):
    c = mul(add(s[root], s[end]), .5); d = sub(s[mid], c)
    return add(s[mid], mul(nrm(d) if ln(d) > .5 else (1, 0, 0), 40))

scene = bpy.context.scene
scene.render.fps = DATA.get("fps", 24)
keys = [dict(k, pose=ground(k)) for k in DATA["keys"]]
scene.frame_start, scene.frame_end = keys[0]["f"], keys[-1]["f"]
name = DATA["title"].replace(" Storyboard", "")

arm = bpy.data.armatures.new(name + " Rig"); arm.display_type = "STICK"
rig = bpy.data.objects.new(name + " Rig", arm); scene.collection.objects.link(rig)
bpy.context.view_layer.objects.active = rig
rest = raw(keys[0]["pose"])
bpy.ops.object.mode_set(mode="EDIT")
for b, h, t, par in BONES:
    eb = arm.edit_bones.new(b); eb.head, eb.tail = V(rest[h]), V(rest[t])
    if par: eb.parent = arm.edit_bones[par]
bpy.ops.object.mode_set(mode="OBJECT")

# IK controls: hand/foot targets and elbow/knee poles you can grab and move in Blender
def empty(n, shape, size):
    e = bpy.data.objects.new(n, None); e.empty_display_type = shape; e.empty_display_size = size
    scene.collection.objects.link(e); return e
ctrl = {}
for bone, root, mid, end, cn in CHAINS:
    ctrl[cn] = empty(cn, "CUBE", .04); ctrl[cn + ".pole"] = empty(cn + ".pole", "SPHERE", .03)
    ctrl[cn].location = V(rest[end]); ctrl[cn + ".pole"].location = V(pole_pos(rest, root, mid, end))
bpy.context.view_layer.update()

bpy.context.view_layer.objects.active = rig
bpy.ops.object.mode_set(mode="POSE")
for pb in rig.pose.bones: pb.rotation_mode = "QUATERNION"
for bone, root, mid, end, cn in CHAINS:
    c = rig.pose.bones[bone].constraints.new("IK")
    c.target = ctrl[cn]; c.pole_target = ctrl[cn + ".pole"]; c.chain_count = 2
# calibrate pole angles so Blender's IK lands exactly where the preview's IK does
bpy.context.view_layer.update()
for bone, root, mid, end, cn in CHAINS:
    c = rig.pose.bones[bone].constraints["IK"]; best = None
    for a in range(-180, 180, 1):
        c.pole_angle = math.radians(a); bpy.context.view_layer.update()
        err = (rig.matrix_world @ rig.pose.bones[bone].head - V(rest[mid])).length
        if best is None or err < best[0]: best = (err, a)
    c.pole_angle = math.radians(best[1])

def ipo(obj, frame, kind):
    ad = obj.animation_data
    if not ad or not ad.action: return
    fcs = getattr(ad.action, "fcurves", None)
    if fcs is None:
        fcs = [fc for l in ad.action.layers for st in l.strips for cb in st.channelbags for fc in cb.fcurves]
    for fc in fcs:
        for kp in fc.keyframe_points:
            if abs(kp.co[0] - frame) < .01: kp.interpolation = kind

props = {}
bpy.ops.object.mode_set(mode="OBJECT")
for pn, d in DATA.get("props", {}).items():
    xs = [s[0] for s in d["shapes"]] + [s[0] + s[2] for s in d["shapes"]]
    ys = [s[1] for s in d["shapes"]] + [s[1] + s[3] for s in d["shapes"]]
    bpy.ops.mesh.primitive_cube_add(size=1); ob = bpy.context.active_object; ob.name = pn
    ob.dimensions = ((max(xs) - min(xs)) * S, 0.03, (max(ys) - min(ys)) * S)
    bpy.ops.object.transform_apply(scale=True)
    ob.data.transform(Matrix.Translation(Vector((((max(xs) + min(xs)) / 2) * S, 0, -((max(ys) + min(ys)) / 2) * S))))
    props[pn] = ob
bpy.context.view_layer.objects.active = rig
bpy.ops.object.mode_set(mode="POSE")

ANCH = {"rH": "rH", "lH": "lH", "fFoot": "fAn", "bFoot": "bAn", "hip": "hip", "head": "hd", "chest": "sh"}
def side_ang(a, b, fwd):
    h = math.hypot(b[0] - a[0], b[2] - a[2]) * (1 if (b[0] - a[0]) * fwd[0] + (b[2] - a[2]) * fwd[2] >= 0 else -1)
    return math.degrees(math.atan2(b[1] - a[1], h))

for k in keys:
    f = k["f"]; p = k["pose"]; scene.frame_set(f); s = raw(p)
    for bone, root, mid, end, cn in CHAINS:
        ctrl[cn].location = V(s[end]); ctrl[cn].keyframe_insert("location", frame=f)
        ctrl[cn + ".pole"].location = V(pole_pos(s, root, mid, end)); ctrl[cn + ".pole"].keyframe_insert("location", frame=f)
    bpy.context.view_layer.update()
    for b, h, t, par in BONES:
        if b in FK or b.startswith("foot."):
            pb = rig.pose.bones[b]; pb.matrix = bone_matrix(s[h], s[t]); bpy.context.view_layer.update()
            pb.keyframe_insert("location", frame=f); pb.keyframe_insert("rotation_quaternion", frame=f)
    fwd = rotY((1, 0, 0), (0, 0, 0), p["turn"]); tw = p["turn"] + p["twist"]
    angs = {"rH": side_ang(s["rE"], s["rH"], fwd), "lH": side_ang(s["lE"], s["lH"], fwd), "fFoot": side_ang(s["fAn"], s["fTo"], fwd),
            "bFoot": side_ang(s["bAn"], s["bTo"], fwd), "hip": p["lean"], "head": p["head"], "chest": p["lean"] + p["chest"], "world": 0}
    yaws = {"rH": tw, "lH": tw, "chest": tw, "head": tw + p["look"], "fFoot": p["turn"], "bFoot": p["turn"], "hip": p["turn"], "world": 0}
    for pn, ob in props.items():
        pr = k.get("props", {}).get(pn)
        ob.hide_viewport = ob.hide_render = pr is None
        ob.keyframe_insert("hide_viewport", frame=f); ob.keyframe_insert("hide_render", frame=f)
        if pr is None: continue
        if pr["at"] == "world":
            pos, rot, yaw = (pr.get("x", 0), pr.get("y", 0), pr.get("z", 0)), pr.get("r", 0), pr.get("yaw", 0)
        else:
            base = angs[pr["at"]] if pr.get("follow") else 0; yaw = yaws[pr["at"]] + pr.get("yaw", 0)
            g = math.radians(base); x, y = pr.get("x", 0), pr.get("y", 0)
            off = rotY((x * math.cos(g) - y * math.sin(g), x * math.sin(g) + y * math.cos(g), pr.get("z", 0)), (0, 0, 0), yaw)
            anc = s[ANCH[pr["at"]]] if pr["at"] != "head" else limb(s["nk"], -90 + p["lean"] + p["chest"] + p["head"] * .6, L["head"])
            pos = add(anc, off); rot = base + pr.get("r", 0)
        ob.location = V(pos); ob.rotation_euler = (0, math.radians(rot), math.radians(yaw))
        ob.keyframe_insert("location", frame=f); ob.keyframe_insert("rotation_euler", frame=f)

for i, k in enumerate(keys):
    if i + 1 < len(keys) and keys[i + 1].get("snap"):
        for ob in [rig] + list(ctrl.values()) + list(props.values()):
            ipo(ob, k["f"], "LINEAR")

bpy.ops.object.mode_set(mode="OBJECT")
scene.frame_set(keys[0]["f"])
print("Built", name, "with real IK:", len(keys), "keys on frames", [k["f"] for k in keys])
